const { useEffect, useRef, useState } = React;

const OPTIONS = [
  { value: "auto", note: "滚动链穿透" },
  { value: "contain", note: "不穿透，保留回弹" },
  { value: "none", note: "不穿透，无回弹" },
];
const CHAIN_WINDOW_MS = 200;

const Meter = ({ label, value, max, highlight }) => (
  <div className="flex flex-col gap-1">
    <div className="flex items-baseline justify-between">
      <span className="text-tau-sm text-ink-2">{label}</span>
      <span className="font-tau-mono text-tau-sm text-ink-1">{Math.round(value)}px</span>
    </div>
    <div className="h-1.5 overflow-hidden rounded-full bg-track">
      <div
        className={`h-full rounded-full transition-colors ${highlight ? "bg-danger" : "bg-accent"}`}
        style={{ width: `${max ? (value / max) * 100 : 0}%` }}
      />
    </div>
  </div>
);

const Placeholder = ({ width }) => <div className={`h-3 rounded-full bg-hover ${width}`} />;

const Component = () => {
  const outerRef = useRef(null);
  const innerRef = useRef(null);
  const dialogRef = useRef(null);
  const wheelAtRef = useRef(0);
  const flashTimerRef = useRef(0);
  const [value, setValue] = useState("auto");
  const [scroll, setScroll] = useState({ outer: 0, outerMax: 0, inner: 0, innerMax: 0 });
  const [chained, setChained] = useState(0);
  const [flash, setFlash] = useState(false);

  const measure = () => {
    const outer = outerRef.current;
    const inner = innerRef.current;
    setScroll({
      outer: outer.scrollTop,
      outerMax: outer.scrollHeight - outer.clientHeight,
      inner: inner.scrollTop,
      innerMax: inner.scrollHeight - inner.clientHeight,
    });
  };

  // 外层滚动框滚到让弹窗居中，内层回到顶部
  const reset = () => {
    const outer = outerRef.current;
    const dialog = dialogRef.current;
    outer.scrollTop = dialog.offsetTop - (outer.clientHeight - dialog.offsetHeight) / 2;
    innerRef.current.scrollTop = 0;
    setChained(0);
    measure();
  };

  useEffect(() => {
    const outer = outerRef.current;
    const inner = innerRef.current;
    reset();
    // 滚轮落在内层时记下时间，紧接着外层发生滚动即视为滚动链穿透
    const handleWheel = () => {
      wheelAtRef.current = performance.now();
    };
    const handleOuterScroll = () => {
      if (performance.now() - wheelAtRef.current < CHAIN_WINDOW_MS) {
        setChained(count => count + 1);
        setFlash(true);
        clearTimeout(flashTimerRef.current);
        flashTimerRef.current = setTimeout(() => setFlash(false), 400);
      }
      measure();
    };
    inner.addEventListener("wheel", handleWheel, { passive: true });
    inner.addEventListener("scroll", measure, { passive: true });
    outer.addEventListener("scroll", handleOuterScroll, { passive: true });
    return () => {
      inner.removeEventListener("wheel", handleWheel);
      inner.removeEventListener("scroll", measure);
      outer.removeEventListener("scroll", handleOuterScroll);
      clearTimeout(flashTimerRef.current);
    };
  }, []);

  const choose = next => {
    setValue(next);
    reset();
  };

  return (
    <div className="@container flex flex-col gap-3">
      <div className="flex flex-wrap items-center gap-2">
        {OPTIONS.map(option => (
          <button
            key={option.value}
            type="button"
            aria-pressed={value === option.value}
            onClick={() => choose(option.value)}
            className={`flex cursor-pointer items-center gap-2 rounded-full border px-3 py-1 transition-colors ${
              value === option.value ? "border-accent bg-accent-soft text-accent-text" : "border-line-1 bg-surface text-ink-2 hover:bg-hover"
            }`}
          >
            <span className="font-tau-mono text-tau-sm">{option.value}</span>
            <span className="text-tau-tiny text-ink-3">{option.note}</span>
          </button>
        ))}
        <ui.Button variant="ghost" size="sm" icon={icons.RotateCcw} className="ml-auto" onClick={reset}>
          重置
        </ui.Button>
      </div>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(220px,34%)]">
        <div ref={outerRef} className="relative h-[280px] min-w-0 overflow-y-auto rounded-tau-md border border-line-1">
          <div className="flex flex-col gap-3 p-4">
            {["w-2/5", "w-full", "w-11/12", "w-full", "w-3/5", "w-full", "w-4/5"].map((width, index) => (
              <Placeholder key={index} width={width} />
            ))}
            <div ref={dialogRef} className="my-2 flex flex-col rounded-tau-md border border-line-1 bg-surface shadow-card">
              <div className="flex items-center gap-2 border-b border-line-2 px-3 py-2">
                <span className="text-tau-body text-ink-1">弹窗</span>
                <code className="ml-auto rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-tiny text-ink-2">
                  overscroll-behavior: {value}
                </code>
              </div>
              <div ref={innerRef} className="h-[140px] overflow-y-auto" style={{ overscrollBehavior: value }}>
                {Array.from({ length: 10 }, (_, index) => (
                  <div key={index} className="border-b border-line-2 px-3 py-1.5 text-tau-body text-ink-2 last:border-b-0">
                    弹窗内容 {index + 1}
                  </div>
                ))}
              </div>
            </div>
            {["w-full", "w-3/4", "w-full", "w-11/12", "w-1/2", "w-full", "w-4/5", "w-2/3"].map((width, index) => (
              <Placeholder key={index} width={width} />
            ))}
          </div>
        </div>
        <div className="flex flex-col gap-3 rounded-tau-md border border-line-1 p-3">
          <span className="text-tau-sm text-ink-3">滚动位置</span>
          <Meter label="弹窗 scrollTop" value={scroll.inner} max={scroll.innerMax} />
          <Meter label="页面 scrollTop" value={scroll.outer} max={scroll.outerMax} highlight={flash} />
          <div className={`mt-auto flex items-center gap-2 rounded-tau-sm px-2.5 py-2 transition-colors ${chained ? "bg-danger-soft" : "bg-ok-soft"}`}>
            {chained ? <icons.TriangleAlert className="size-4 shrink-0 text-danger" /> : <icons.ShieldCheck className="size-4 shrink-0 text-ok" />}
            <span className={`text-tau-sm ${chained ? "text-danger" : "text-ok"}`}>
              {chained ? `页面被带动滚动 ${chained} 次` : "页面未被带动"}
            </span>
          </div>
          <p className="m-0 text-tau-meta text-ink-3">在弹窗里滚到底后继续滚动</p>
        </div>
      </div>
    </div>
  );
};
